class Solution:
    def imageSmoother(self, img: List[List[int]]) -> List[List[int]]:
        m, n = len(img), len(img[0])
        res = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                total = cnt = 0
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni, nj = i+di, j+dj
                        if 0<=ni<m and 0<=nj<n:
                            total += img[ni][nj]
                            cnt += 1
                res[i][j] = total // cnt
        return res

class Solution:
    def widthOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        if not root: return 0
        ans = 0
        queue = [(root, 0)]
        while queue:
            ans = max(ans, queue[-1][1] - queue[0][1] + 1)
            nxt = []
            for node, idx in queue:
                if node.left: nxt.append((node.left, 2*idx))
                if node.right: nxt.append((node.right, 2*idx+1))
            queue = nxt
        return ans

class Solution:
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        dp = [[0]*n for _ in range(n)]
        for i in range(n-1,-1,-1):
            dp[i][i] = 1
            for j in range(i+1,n):
                if s[i] == s[j]:
                    dp[i][j] = dp[i][j-1]
                else:
                    dp[i][j] = min(dp[i][k]+dp[k+1][j] for k in range(i,j))
