class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        if len(cards) == 1:
            return abs(cards[0] - 24) < 1e-6
        for i in range(len(cards)):
            for j in range(len(cards)):
                if i == j: continue
                rest = [cards[k] for k in range(len(cards)) if k!=i and k!=j]
                for op in range(4):
                    if op == 0: rest.append(cards[i]+cards[j])
                    elif op == 1: rest.append(cards[i]-cards[j])
                    elif op == 2: rest.append(cards[i]*cards[j])
                    else:
                        if cards[j] == 0: continue
                        rest.append(cards[i]/cards[j])
                    if self.judgePoint24(rest): return True
                    rest.pop()
        return False

class Solution:
    def validPalindrome(self, s: str) -> bool:
        def isPalin(l, r):
            while l < r:
                if s[l] != s[r]: return False
                l += 1; r -= 1
            return True
        l, r = 0, len(s)-1
        while l < r:
            if s[l] != s[r]:
                return isPalin(l+1, r) or isPalin(l, r-1)
            l += 1; r -= 1
        return True

