        self.ans = 0
        def dfs(node):
            if not node: return 0
            l, r = dfs(node.left), dfs(node.right)
            al = l+1 if node.left and node.left.val == node.val else 0
            ar = r+1 if node.right and node.right.val == node.val else 0
