class Solution:
    def minStickers(self, stickers, target):
        n = len(target)
        N = 1 << n
        dp = [float('inf')] * N
        dp[0] = 0
        for state in range(N):
            if dp[state] == float('inf'): continue
            for sticker in stickers:
                cur = state
                for c in sticker:
                    for i in range(n):
                        if target[i]==c and not (cur>>i&1):
                            cur |= 1<<i
                            break
                dp[cur] = min(dp[cur], dp[state]+1)
        return dp[N-1] if dp[N-1] != float('inf') else -1

