class Solution:
    def numDistinctIslands(self, grid):
        m, n = len(grid), len(grid[0])
        visited = set()
        shapes = set()
        def dfs(r, c, r0, c0, path):
            if 0<=r<m and 0<=c<n and grid[r][c]==1 and (r,c) not in visited:
                visited.add((r,c))
                path.append((r-r0, c-c0))
                dfs(r+1,c,r0,c0,path)
                dfs(r-1,c,r0,c0,path)
                dfs(r,c+1,r0,c0,path)
                dfs(r,c-1,r0,c0,path)
        for i in range(m):
            for j in range(n):
                if grid[i][j]==1 and (i,j) not in visited:
                    path = []
                    dfs(i,j,i,j,path)
                    shapes.add(tuple(path))
        return len(shapes)

class Solution:
