class Solution:
    def canPartitionKSubsets(self, nums, k):
        target, rem = divmod(sum(nums), k)
        if rem: return False
        nums.sort(reverse=True)
        buckets = [0]*k
        def bt(idx):
            if idx == len(nums): return all(b==target for b in buckets)
            seen = set()
            for i in range(k):
                if buckets[i]+nums[idx]>target: continue
                if buckets[i] in seen: continue
                seen.add(buckets[i])
                buckets[i] += nums[idx]
                if bt(idx+1): return True
                buckets[i] -= nums[idx]
            return False
        return bt(0)

