class MyLinkedList:
    def __init__(self):
        self.head = Node()
        self.size = 0
    def get(self, index):
        if index < 0 or index >= self.size: return -1
        cur = self.head.next
        for _ in range(index): cur = cur.next
        return cur.val
    def addAtHead(self, val): self.addAtIndex(0, val)
    def addAtTail(self, val): self.addAtIndex(self.size, val)
    def addAtIndex(self, index, val):
        if index > self.size: return
        index = max(0, index)
        cur = self.head
        for _ in range(index): cur = cur.next
        node = Node(val)
        node.next = cur.next
        cur.next = node
        self.size += 1
    def deleteAtIndex(self, index):
        if index < 0 or index >= self.size: return
        cur = self.head
        for _ in range(index): cur = cur.next
        cur.next = cur.next.next
        self.size -= 1

class Solution:
    def insert(self, head, insertVal):
        node = Node(insertVal)
        if not head:
            node.next = node
            return node
        prev, curr = head, head.next
        while True:
            if prev.val <= insertVal <= curr.val: break
            if prev.val > curr.val:
                if insertVal >= prev.val or insertVal <= curr.val: break
            prev, curr = curr, curr.next
            if prev == head: break
        prev.next = node
        node.next = curr
        return head

