class RangeModule:
    def __init__(self):
        self.intervals = []
    def addRange(self, left, right):
        new = []
        placed = False
        for l, r in self.intervals:
            if r < left: new.append((l,r))
            elif l > right:
                if not placed: new.append((left,right)); placed=True
                new.append((l,r))
