    def queryRange(self, left, right):
        for l, r in self.intervals:
            if l <= left and r >= right: return True
        return False
    def removeRange(self, left, right):
        new = []
        for l, r in self.intervals:
            if r <= left or l >= right: new.append((l,r))
            else:
                if l < left: new.append((l,left))
                if r > right: new.append((right,r))
        self.intervals = new

