class Solution:
    def smallestDistancePair(self, nums, k):
        nums.sort()
        lo, hi = 0, nums[-1]-nums[0]
        while lo < hi:
            mid = (lo+hi)//2
            count = left = 0
            for right in range(len(nums)):
                while nums[right]-nums[left] > mid: left += 1
                count += right-left
            if count < k: lo = mid+1
            else: hi = mid
        return lo

